function mountCalendar(){const el=$('#calendar');if(!el||typeof FullCalendar==='undefined'){if(el)el.innerHTML='<p class="empty">Chưa tải được thư viện lịch. Hãy tải lại trang.</p>';return}const small=window.matchMedia('(max-width: 760px)').matches;if(!calendarInitialized){if(small)calendarViewType='timeGridDay';calendarInitialized=true}const events=getSessions().filter(e=>!calendarFilter.has(e.courseId)).map(sessionToCalendar);calendarInstance=new FullCalendar.Calendar(el,{locale:'vi',timeZone:'local',now:'2026-11-12T12:00:00',initialDate:calendarDate,initialView:calendarViewType,firstDay:1,headerToolbar:false,allDaySlot:false,height:small?650:735,expandRows:true,slotMinTime:'06:00:00',slotMaxTime:'24:00:00',slotDuration:'00:30:00',slotLabelInterval:'01:00:00',slotLabelFormat:{hour:'2-digit',minute:'2-digit',hour12:false},scrollTime:'16:00:00',scrollTimeReset:false,dayHeaderFormat:{weekday:'short',day:'numeric',month:'numeric'},editable:true,selectable:true,selectMirror:true,eventResizableFromStart:true,eventMinHeight:36,eventShortHeight:45,eventDisplay:'block',dayMaxEvents:3,events,datesSet:info=>{calendarDate=dateLocal(info.view.calendar.getDate());$('#calTitle').textContent=info.view.title;calendarViewType=info.view.type;$$('[data-cal-view]').forEach(b=>{b.classList.toggle('active',b.dataset.calView===calendarViewType);b.setAttribute('aria-pressed',String(b.dataset.calView===calendarViewType))})},eventContent:arg=>({html:`<div class="study-event"><span class="event-time">${esc(arg.timeText)}</span><strong>${esc(arg.event.title)}</strong><span class="event-course">${esc(arg.event.extendedProps.courseName)}</span></div>`}),eventClick:info=>editSession(info.event.id),dateClick:info=>sessionEditor(null,info.dateStr.slice(0,10),info.allDay?'18:00':info.dateStr.slice(11,16)),eventDrop:calendarMove,eventResize:calendarMove});calendarInstance.render();$('#calToday').onclick=()=>calendarInstance.gotoDate('2026-11-12');$('#calPrev').onclick=()=>calendarInstance.prev();$('#calNext').onclick=()=>calendarInstance.next();$$('[data-cal-view]').forEach(b=>b.onclick=()=>{calendarViewType=b.dataset.calView;calendarInstance.changeView(calendarViewType)});$$('[data-calendar-filter]').forEach(b=>b.onclick=()=>{const id=b.dataset.calendarFilter;calendarFilter.has(id)?calendarFilter.delete(id):calendarFilter.add(id);render()});const panel=$('#telegramPanel');panel.hidden=!telegramOpen;if(telegramOpen)$('#telechat').scrollTop=99999;}
function calendarMove(info){const e=info.event,start=e.start,end=e.end;if(!start||!end){info.revert();return}const date=start.getFullYear()+'-'+String(start.getMonth()+1).padStart(2,'0')+'-'+String(start.getDate()).padStart(2,'0'),time=String(start.getHours()).padStart(2,'0')+':'+String(start.getMinutes()).padStart(2,'0'),duration=Math.round((end-start)/60000);const err=validateSession(e.id,date,time,duration);if(err){info.revert();toast(err);return}storeSession(e.id,{date,time,duration});toast('Đã đổi lịch: '+e.title);}
function validateSession(id,date,time,duration){if(!date||!time||duration<5||duration>180)return 'Mỗi buổi cần từ 5 đến 180 phút.';const mins=Number(time.slice(0,2))*60+Number(time.slice(3));if(mins+duration>1440)return 'Chọn buổi học kết thúc trong cùng ngày nhé.';const other=sessionConflict(id,date,time,duration);return other?'Trùng buổi “'+other.title+'” lúc '+other.time+'. Chọn giờ khác nhé.':null}
function editSession(id){const e=getSessions().find(e=>e.id===id);if(e)sessionEditor(e)}
function sessionEditor(existing=null,date='2026-11-12',time='18:00'){const e=existing||{courseId:courseId,title:'',date,time,duration:45};openModal(`<div class="eyebrow">${existing?'ĐIỀU CHỈNH BUỔI HỌC':'THÊM VÀO LỊCH CHUNG'}</div><h2>${existing?'Sắp lại một chút, học tiếp nhé.':'Dành một khoảng cho việc học.'}</h2><form id="sessionForm"><label class="form-label">Môn học<select id="sessionCourse" ${e.primary?'disabled':''}>${state.courses.map(c=>`<option value="${c.id}" ${c.id===e.courseId?'selected':''}>${esc(c.name)}</option>`).join('')}</select></label><label class="form-label">Nội dung buổi học<input id="sessionTitle" value="${esc(e.title)}" placeholder="Ví dụ: Ôn Bayes & làm quiz" maxlength="100" required></label><div class="session-form-row"><label class="form-label">Ngày<input type="date" id="sessionDate" value="${e.date}" required></label><label class="form-label">Bắt đầu<input type="time" id="sessionTime" value="${e.time}" required></label><label class="form-label">Phút<input type="number" id="sessionDuration" min="5" max="180" value="${e.duration}" required></label></div><p id="sessionError" class="inline-error" role="alert"></p><div class="session-form-buttons">${existing?'<button class="secondary" type="button" id="sessionStart">'+ui('player-play')+' Vào học</button>':''}${existing&&!e.primary?'<button class="textbutton danger" type="button" id="sessionDelete">Xóa buổi</button>':''}<button class="primary" type="submit">${existing?'Lưu lịch mới':'Thêm buổi học'}</button></div></form>`);$('#sessionForm').onsubmit=event=>{event.preventDefault();const update={courseId:$('#sessionCourse').value,title:$('#sessionTitle').value.trim(),date:$('#sessionDate').value,time:$('#sessionTime').value,duration:Number($('#sessionDuration').value)};if(!update.title){$('#sessionError').textContent='Nhập nội dung buổi học nhé.';return}const err=validateSession(e.id,update.date,update.time,update.duration);if(err){$('#sessionError').textContent=err;return}if(existing)storeSession(e.id,update);else{state.extraSessions.push({id:'session-'+Date.now(),...update});save()}calendarDate=update.date;$('#modal').close();render();toast(existing?'Đã lưu lịch mới':'Đã thêm buổi học vào lịch')};if(existing){$('#sessionStart').onclick=()=>{$('#modal').close();go('course',e.courseId,'study')};if(!e.primary)$('#sessionDelete').onclick=()=>{state.extraSessions=state.extraSessions.filter(s=>s.id!==e.id);save();$('#modal').close();render();toast('Đã xóa buổi học')}}}
function studyView(c){const fs=filesFor(c),f=fs.find(s=>s.id===sourceFocus)||fs[0];sourceFocus=f?.id;return `<div class="lesson-topbar"><div class="lesson-heading"><button class="lesson-back" data-course="${c.id}" aria-label="Về môn học">‹</button>${icon(c)}<div><div class="lesson-eyebrow">${esc(c.name)} <span> / </span> BÀI ĐANG HỌC</div><h1>${esc(c.lesson)}</h1></div></div><div class="lesson-actions"><button class="secondary" data-action="toggleTutor">${ui(hideTutor?'sparkles':'book')} ${hideTutor?'Mở gia sư':'Chỉ đọc bài'}</button><button class="secondary" data-action="focusLesson">${ui('layout-dashboard')} ${focusLesson?'Thoát tập trung':'Tập trung'}</button><button class="primary" data-action="quiz">${ui('pencil')} Kiểm tra nhanh</button></div></div><div class="lesson-sourcebar"><button class="textbutton bridge-start" data-tab="bridge">${ui('sparkles')} Học với ChatGPT đang có</button><span>${ui('books')} ${fs.length} nguồn</span><span>${ui('clock')} ${c.duration} phút dự kiến</span><button class="textbutton" data-tab="sources">Quản lý tài liệu ${ui('arrow-up-right')}</button></div><div class="desk lesson-desk ${hideTutor?'reader-only':''}" style="--reader-font:${readerSize}px"><section class="reader-pane" id="lessonReader"><div class="pane-heading"><div class="reader-source-select"><label for="sourceSelect">${ui('book')} ĐANG ĐỌC</label><select id="sourceSelect" aria-label="Chọn tài liệu đọc">${fs.map(s=>`<option value="${s.id}" ${s.id===f?.id?'selected':''}>${esc(s.name)}</option>`).join('')}</select></div><div class="reading-tools"><button class="icon-button" data-action="smallerText" aria-label="Giảm cỡ chữ">A−</button><span>${readerSize}</span><button class="icon-button" data-action="largerText" aria-label="Tăng cỡ chữ">A+</button></div></div><div class="reader-scroll"><div class="lesson-document-meta"><span class="document-badge">BÀI HỌC</span><span>Nội dung minh họa · không phải toàn văn sách</span></div>${readerContent(c,f)}${lessonIllustration(c)}<div class="lesson-checkpoint"><div>${ui('circle-check')}<strong>Trước khi đi tiếp</strong></div><p>Thử giải thích ý chính bằng lời của bạn. Nếu còn vướng, trao đổi với gia sư hoặc lưu một ghi chú để quay lại.</p><div><button class="primary" data-study-prompt="Tao muốn tự giải thích bài này, hãy hỏi tao từng câu">${ui('sparkles')} Cùng gia sư kiểm tra</button><button class="secondary" data-action="openNotes">${ui('notes')} Ghi lại điều vừa hiểu</button></div></div></div><div class="reader-bottom"><span>${ui('circle-check')} Tiến độ & ghi chú lưu riêng theo môn</span><button class="textbutton" data-action="quiz">Làm quiz bài này ${ui('arrow-right')}</button></div></section>${hideTutor?'':`<section class="tutor-pane" id="lessonTutor"><div class="desk-tabs"><button data-mode="chat" class="${studyMode==='chat'?'active':''}">${ui('sparkles')} Gia sư của bạn</button><button data-mode="notes" class="${studyMode==='notes'?'active':''}">${ui('notes')} Ghi chú</button></div>${studyMode==='notes'?`<div class="notes-pane"><div class="notes-title"><span class="notes-symbol">${ui('pencil')}</span><h3>Điều bạn vừa hiểu.</h3></div><p class="muted">Viết theo cách của bạn. Ghi chú được giữ riêng cho môn này.</p><textarea id="notes" aria-label="Ghi chú của môn học" placeholder="Ý chính, ví dụ của mình, câu hỏi còn bỏ ngỏ…">${esc(c.notes)}</textarea><div class="muted" id="noteStatus">Đã lưu trên trình duyệt.</div><button class="secondary" data-action="exportNotes">${ui('download')} Xuất ghi chú</button></div>`:`<div class="tutor-profile"><span>${ui('brain')}</span><div><strong>Cùng hiểu, cùng phản biện.</strong><small>Hội thoại minh họa · chưa nối AI</small></div><i></i></div><div class="desk-chat" id="chatmessages"><div class="message tutor-intro"><small>GIA SƯ · ${esc(c.name.toUpperCase())}</small>${c.id==='stats'?'Thử nghĩ cùng mình nhé: hai biến cố <strong>độc lập</strong> có thể xảy ra đồng thời không? Bạn cứ nói cách hiểu, mình sẽ giúp kiểm tra lập luận.':`Hôm nay mình cùng học <strong>${esc(c.lesson.toLowerCase())}</strong>. Bạn muốn thử một ví dụ, phản biện một ý hay tự giải một bài?`}<div class="ref">${ui('books')} Đang dùng ${fs.length} nguồn trong môn này</div></div>${c.messages.map(m=>`<div class="message ${m.role==='user'?'mine':''}"><small>${m.role==='user'?'BẠN':'GIA SƯ · PHẢN HỒI MẪU'}</small>${esc(m.text)}${m.role!=='user'&&f?.sample?`<button class="citation" data-open-source="${f.id}">${ui('file-text')} Nguồn minh họa</button>`:''}</div>`).join('')}${!c.messages.length?`<div class="tutor-starters"><span>BẮT ĐẦU TỪ MỘT CÂU HỎI</span><button data-study-prompt="Giải thích bằng ví dụ khác"><i class="starter-purple">${ui('sparkles')}</i><div><strong>Cho tôi một ví dụ khác</strong><small>Gần gũi, trực quan hơn</small></div>${ui('arrow-up-right')}</button><button data-study-prompt="Phản biện cách hiểu của tao"><i class="starter-orange">${ui('brain')}</i><div><strong>Cùng phản biện một chút</strong><small>Tìm giả định và phản ví dụ</small></div>${ui('arrow-up-right')}</button><button data-study-prompt="So sánh các nguồn đang chọn"><i class="starter-blue">${ui('books')}</i><div><strong>Kết nối các tài liệu</strong><small>Thêm góc nhìn cho cùng một ý</small></div>${ui('arrow-up-right')}</button></div>`:''}</div><div class="desk-chat-bottom"><form class="chatform" id="studyform"><label class="sr-only" for="tutorInput">Tin nhắn cho gia sư</label><input id="tutorInput" aria-label="Hỏi gia sư" placeholder="Hỏi đến khi bạn thật sự hiểu…" required><button class="primary" aria-label="Gửi cho gia sư">${ui('arrow-up')}</button></form><span class="mock-hint">${ui('sparkles')} Không cần câu hỏi hoàn hảo. Cứ bắt đầu từ điều bạn đang nghĩ.</span></div>`}</section>`}</div>`}
function mountLesson(){if(hideTutor||typeof Split==='undefined'||!window.matchMedia('(min-width: 1100px)').matches)return;splitInstance=Split(['#lessonReader','#lessonTutor'],{sizes:[64,36],minSize:[420,320],gutterSize:12,snapOffset:0,elementStyle:(dimension,size,gutter)=>({'flex-basis':`calc(${size}% - ${gutter}px)`}),gutterStyle:(dimension,gutter)=>({'flex-basis':gutter+'px'}),onDragEnd:()=>{}})}
function lessonIllustration(c){if(c.id==='stats')return `<div class="lesson-illustration"><div class="illustration-heading"><span>NHÌN THẤY Ý TƯỞNG</span><strong>6 khả năng. 3 kết quả thuận lợi.</strong></div><div class="dice-outcomes">${[1,2,3,4,5,6].map(n=>`<div class="outcome ${n%2===0?'favorable':''}"><span>${n}</span><small>${n%2===0?'CHẴN':'LẺ'}</small></div>`).join('')}</div><div class="probability-formula"><span>P(số chẵn)</span><b>=</b><strong>3 / 6</strong><b>=</b><strong>½</strong></div><p>Các ô màu tím thuộc biến cố A. Điều kiện: xúc xắc cân đối, mỗi kết quả đồng khả năng.</p></div>`;if(c.id==='python')return `<div class="lesson-illustration python-demo"><div class="illustration-heading"><span>TỰ THỬ MỘT CHÚT</span><strong>Từ danh sách đến kết quả.</strong></div><pre><span>numbers</span> = [1, 2, 3]
<b>for</b> item <b>in</b> numbers:
    <i>print</i>(item * 2)</pre><div class="code-output"><span>KẾT QUẢ</span><strong>2 &nbsp; 4 &nbsp; 6</strong></div></div>`;if(c.id==='english')return `<div class="lesson-illustration english-demo"><div class="illustration-heading"><span>NÓI THEO CÁCH CỦA BẠN</span><strong>Đổi một câu. Kể câu chuyện của mình.</strong></div><div class="dialogue-line"><span>A</span><p>What does your typical workday look like?</p></div><div class="dialogue-line"><span>B</span><p>I usually start work at nine. In the morning, I…</p></div><p>Thay phần cuối bằng hoạt động thật của bạn, rồi thử nói thành tiếng.</p></div>`;return ''}
actions.newSession=()=>sessionEditor();actions.toggleTelegram=()=>{telegramOpen=!telegramOpen;const p=$('#telegramPanel');if(p){p.hidden=!telegramOpen;if(telegramOpen)p.scrollIntoView({behavior:'smooth',block:'start'})}};actions.toggleTutor=()=>{hideTutor=!hideTutor;render()};actions.focusLesson=()=>{focusLesson=!focusLesson;render()};actions.smallerText=()=>{readerSize=Math.max(15,readerSize-1);render()};actions.largerText=()=>{readerSize=Math.min(23,readerSize+1);render()};actions.openNotes=()=>{hideTutor=false;studyMode='notes';render()};
